Procedure I compiled with help from Przemek 

{noformat}USE taxify_support_case_read_status;
DROP PROCEDURE if exists delete_old_unread_cases;

DELIMITER $$
CREATE PROCEDURE delete_old_unread_cases()
BEGIN

    DECLARE v_min_id, v_max_id BIGINT;
	DECLARE v_batch_size INT DEFAULT 2000;

    DECLARE v_sleep_cnt INT DEFAULT 0;
    DECLARE v_sleep_after INT DEFAULT 1000;
    DECLARE v_sleep_time INT DEFAULT 3;

    SELECT 
		MIN(id), MAX(id) 
	INTO 
		v_min_id, v_max_id
	FROM 
		unread_support_case;
    SELECT v_min_id, v_max_id, v_batch_size; 

    WHILE v_min_id <= v_max_id DO

        DELETE FROM
			unread_support_case
		WHERE
            id >= v_min_id AND
            id < v_min_id + v_batch_size AND
            last_message_timestamp < DATE_SUB(NOW(), INTERVAL 60 DAY);
        SET v_min_id = v_min_id + v_batch_size;

        SET v_sleep_cnt = v_sleep_cnt + 1;
        SELECT v_min_id, v_max_id, 100*v_min_id/v_max_id AS completed, v_sleep_cnt, v_sleep_after;

        IF v_sleep_cnt > v_sleep_after THEN
            SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
            SELECT SLEEP(v_sleep_time);
            SET v_sleep_cnt = 0;
        END IF;

    END WHILE;

END;
$$
DELIMITER ;

CALL delete_old_unread_cases();
DROP PROCEDURE if exists delete_old_unread_cases;{noformat}

