{noformat}   private fun scheduleMapAttach() {
        // We want to delay the  map attachment until after the first frame is fully drawn. This way we can minimise the time to initial display
        // in a way imperceptible to the user, as most of the time spend after first frame is spend on fetching the auth state from the backend.
        cancelScheduledMapAtachment()

        mapAttachmentListener = object : ViewTreeObserver.OnGlobalLayoutListener {
            override fun onGlobalLayout() {
                mapAttachmentRunnable = Runnable { router.map.attach() }
                view.post(mapAttachmentRunnable)
                view.viewTreeObserver.removeOnGlobalLayoutListener(this)
            }
        }

        view.viewTreeObserver.addOnGlobalLayoutListener(mapAttachmentListener)
