{code:sql}# using id
USE taxify_fraud;
DROP PROCEDURE IF EXISTS insert_in_loop;

DELIMITER $$
CREATE PROCEDURE insert_in_loop()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 200;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 3;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM taxify_fraud.delivery_order_check_log WHERE created BETWEEN '2022-04-28' AND '2022-07-28 13:00';
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

	INSERT INTO taxify_fraud_logs_storage.delivery_order_calculation
	(check_point,
	 calculation_id,
	 city_id,
	 user_basket_booking_id,
	 score,
	 decision,
	 is_good_decision)
	SELECT 'delivery_order_request', id, city_id, user_basket_booking_id, score, result, (result='PASS' or result='FUSED')
	FROM taxify_fraud.delivery_order_check_log
	WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND created BETWEEN '2022-04-28' AND '2022-07-28 13:00';

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;

CALL insert_in_loop();

DROP PROCEDURE IF EXISTS insert_in_loop;{code}

